

// export default Register;
import React, { useState, useEffect } from 'react';
import { hamburguesas, desserts, drinks } from '../../Variables';
import jsPDF from 'jspdf';

function Register({setConsoleAdmin, consoleAdmin, setNewFetch, newFetch}) {
  const [data, setData] = useState([]);
  const [visibilityData, setVisibilityData] = useState(false);
  const [visibilityInfo, setVisibilityInfo] = useState(false);
  const [dataAdd, setDataAdd] = useState(null);
  const [thisDate, setThisDate] = useState();

  const [visibilityRegister1, setVisibilityRegister1] = useState(true);
  const [visibilityRegister2, setVisibilityRegister2] = useState(false);
  const [visibilityRegister2Food, setVisibilityRegister2Food] = useState(true);
  const [visibilityRegister2Drink, setVisibilityRegister2Drink] = useState(false);
  const [visibilityRegister2Desserts, setVisibilityRegister2Desserts] = useState(false);



  const functionSavePdf = (data) => {
    const pdf = new jsPDF();
  
    const order = JSON.parse(dataAdd); // Asegúrate de que esto sea válido
  
    const registerData = {
      id: data.id,
      imagen: data.imagen,
      name: data.name,
      ingredients: data.ingredients,
      price: data.price,
      revenue: data.totalPayOrder
    };
  
    let yPosition = 20; // Coordenada Y inicial
    
    // Título principal
    pdf.setFontSize(16);
    pdf.text('Registro de Pedido', 90, yPosition);
    yPosition += 10; // Espacio después del título principal
    
    // Detalles del registro
    pdf.setFontSize(12);
    pdf.text(`ID del Registro: ${registerData.id}`, 10, yPosition);
    yPosition += 10;
    pdf.text(`Nombre de la Orden: ${registerData.name}`, 10, yPosition);
    yPosition += 10;
    pdf.text(`Precio: $${registerData.price}`, 10, yPosition);
    yPosition += 10;
    pdf.text(`Ganancia Neta: $${registerData.revenue}`, 10, yPosition);
    yPosition += 15; // Espacio antes de los productos
    
    // Detalles de los productos (si hay productos, en este caso es un array de productos)
    pdf.setFontSize(12);
    pdf.text('Productos:', 10, yPosition);
    yPosition += 10;
    
    const products = JSON.parse(data.products); // Asegúrate de que los productos estén en formato JSON
    products.forEach((product, index) => {
      pdf.text(`${index + 1}. ${product.name} - $${product.price}`, 10, yPosition);
      yPosition += 8; // Espacio entre productos
      pdf.text(`Ingredientes: ${product.ingredients}`, 20, yPosition);
      yPosition += 8; // Espacio entre las líneas
      pdf.text(`Kcal: ${product.kcal}`, 20, yPosition);
      yPosition += 10; // Espacio entre productos
    });
    
    // Agregar más detalles si es necesario...
    
    // Espacio final
    yPosition += 10;
  
    // Guardar el PDF con un nombre dinámico
    pdf.save(`Registro numero ${registerData.id}.pdf`);
  };
  


  const [message, setMessage] = useState("")

  // FUNCIONES DE VISIBILIDAD
  const functionVisibilityOne = () => {
    setVisibilityRegister1(true);
    setVisibilityRegister2(false);
    setVisibilityInfo(true);
  };

  const functionVisibilityTwo = () => {
    setVisibilityRegister1(false);
    setVisibilityRegister2(true);
    setVisibilityInfo(false);
  };

  // CONECCION BACKEND
  useEffect(() => {
    fetch("https://backend-menue.onrender.com/registroGet")
      .then(res => res.json())
      .then(data => {
        setData(data);
        setVisibilityData(true);
        // console.log("esta es la data que llega al registro: " + JSON.stringify(data))
      })
      .catch(err => setConsoleAdmin(prevState => [...prevState, err]));
  }, [newFetch]);

  useEffect(() => {
    setNewFetch(newFetch + 1)
  }, [])

  const showDates = (day) => {
    setDataAdd(day);
    setVisibilityInfo(true);
    setThisDate(day);
if(dataAdd){
    console.log("esta es la estructura de dataAdd " + JSON.stringify(dataAdd))}
  };

  const showDates2 = (date) => {
    const dateSelect = data.find(dateDat => dateDat.date === date.date); // Asegúrate de que comparas correctamente.
    setThisDate(dateSelect);
  };

  // DESCRIPCION REGISTROS
  const functionDescription = () => {
    if (!dataAdd) return null;

    const orders = JSON.parse(dataAdd.data);

    return (
      <div className='container-info-date'>
        <h1>Pedidos:</h1>
        <ul>
          {orders.map((order, index) => {
            const products = JSON.parse(order.products);
            return (
              <li key={index} className='producto'>
                <h2>Pedido ID: {order.id}</h2>
                <ul>
                  {products.map((product, prodIndex) => (
                    <li key={prodIndex} className='list-product-register'>
                      <img src={product.imagen} alt={product.name || "Producto"} />
                      <h3>{product.name} - {product.kcal} kcal</h3>
                      <p>Ingredientes: {product.ingredients}</p>
                      <p>Precio: ${product.price}</p>
                    </li>
                  ))}
                </ul>
                <p>Ganancia de este pedido: ${order.totalPayOrder}</p>
              </li>
            );
          })}
        </ul>
        <div className='container-info-div'>
          <h1>Ganancia neta total:</h1>
          <h2>${dataAdd.totalPay}</h2>
        </div>
        
      </div>
    );
  };

  // FUNCION DE CONTABILIDAD
  const countProduct = (product) => {
    if (!thisDate || !thisDate.data) return <h2>0</h2>;
  
    const orders = JSON.parse(thisDate.data);
    const allProducts = orders.flatMap(order => JSON.parse(order.products));
    const filtProduct = allProducts.filter(pro => pro.name === product);
  
    return <h2>{filtProduct.length}</h2>;
  };

  // MAPEO DE LOS PRODUCTOS
  const mapeoProducts = (food) => {
    {console.log("esta es la estructura de cada item: " + JSON.stringify(food))}

    return (
    
    <div className='container-info-date'>
      <nav>
        <button onClick={() => { setVisibilityRegister2Food(true); setVisibilityRegister2Desserts(false); setVisibilityRegister2Drink(false); }}>Comidas</button>
        <button onClick={() => { setVisibilityRegister2Food(false); setVisibilityRegister2Desserts(false); setVisibilityRegister2Drink(true); }}>Bebidas</button>
        <button onClick={() => { setVisibilityRegister2Food(false); setVisibilityRegister2Desserts(true); setVisibilityRegister2Drink(false); }}>Postres</button>
      </nav>
      {food.map((item, index) => (
        <div key={index} style={{ display: "flex", flexDirection: "row", marginTop: "10px" }}>
          <div className='producto-2'>
            <div style={{ display: "flex", flexDirection: "column", textAlign: "center", width: "80%", marginLeft: "calc(50% - 40%" }}>
              <h1>{item.name}</h1>
              {countProduct(item.name)}
            </div>
            <div style={{ padding: "10px", width: "20%" }} >
              <img src={item.imagen} alt={item.name || "Imagen de producto"} />
            </div>
          </div>
        </div>
      ))}
    </div>
  )};

  // ELIMINAR REGISTROS

  const handleDelete = async (id) => {
    // Preguntar al usuario si está seguro de eliminar el registro
    const confirmation = window.confirm("¿Está seguro de que desea eliminar este registro?");
    
    if (confirmation) {
      try {
        const response = await fetch('https://backend-menue.onrender.com/deleteOneRegister', {
          method: 'DELETE',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ id: id }),
        });
    
        // Esperar que la respuesta sea en formato JSON
        const data = await response.json();
    
        // Verificar si la respuesta es exitosa
        if (response.ok) {
          setNewFetch(prevFetch => prevFetch + 1);  // Utiliza una función de actualización para asegurar que el valor anterior se use correctamente
          alert(`Registro eliminado correctamente`);
        } else {
          // Si la respuesta no es exitosa, mostrar el error recibido
          setMessage(`Error: ${data.error || 'Error desconocido'}`);
        }
      } catch (error) {
        // Manejar errores de red u otros errores
        setMessage(`Error al eliminar el registro: ${error.message}`);
      }
    } else {
      // Si el usuario cancela, no hacer nada
      setMessage('Eliminación cancelada');
    }
  };
    


  // useEffect(() => {
  //   console.log("*******************esta es la estructura de this date: " +   JSON.stringify(thisDate))
  // }, [thisDate])

  // RETURN CENTRAL DE LA APLICACION
  let num = 0
            
  return (
    <div className='container-information-register'>
      <div style={{padding: "5px"}}>
        <button onClick={functionVisibilityOne}>Pedidos</button>
        <button onClick={functionVisibilityTwo}>Conteo</button>
      </div>

      {visibilityData && visibilityRegister1 && (
        <div className='information-register-buttons' style={{padding: "5px"}}>
          {data.map((item, index) => {
            if(num < 1){
            console.log("esta es la estructura de cada item: " + JSON.stringify(item))
          num++;
          }
              // Parsear item.data a un objeto
      const parsedData = JSON.parse(item.data);
            return(
            <div style={{display: "flex", flexDirection: "row", alignItems: "center", justifyContent: "center"}} key={index} className='container-btn-date' >
              <button className='btn-date' onClick={() => showDates(item)}>
                {item.date}
              </button>
              <button onClick={() => handleDelete(item.id)} style={{marginLeft: "5px"}}>X</button>
              {/* {message && <p style={{color: "red"}}>{message}</p>} */}
            </div>
          )})}
        </div>
      )}

      {visibilityData && visibilityRegister2 && (
        <div className='information-register-buttons' style={{padding: "5px"}}>
          {data.map((item, index) => (
            <div style={{display: "flex", flexDirection: "row", alignItems: "center", justifyContent: "center"}} key={index} className='container-btn-date'>
              <button className='btn-date' onClick={() => showDates2(item)}>
                {item.date}
              </button>
              <button onClick={() => functionSavePdf(item)} className='primary-button'>Exportar</button>
              <button onClick={() => handleDelete(item.id)} style={{marginLeft: "5px"}}>X</button>
          </div>
          ))}
        </div>
      )}

      <div className='container-info-date'>
        {visibilityInfo && dataAdd && functionDescription()}
        {visibilityRegister2 && (
          <>
            {visibilityRegister2Food && mapeoProducts(hamburguesas)}
            {visibilityRegister2Desserts && mapeoProducts(desserts)}
            {visibilityRegister2Drink && mapeoProducts(drinks)}
          </>
        )}
      </div>
    </div>
  );
}

export default Register;



