const facturaFunction = (id, totalPay, product) => {
  const iva = totalPay * 1.19
  // Crear la cadena de texto de la factura
  const fecha = new Date().toLocaleDateString();  // Obtiene la fecha en formato 'dd/mm/yyyy'
  const facturaText = `
    FACTURA DE VENTA

    EMISOR:
    Razón Social: Burger-Shop
    NIT: 3446464
    Dirección: avenida siempreviva 123
    Teléfono: 233534
    Email: blablalb@blabla.com

    COMPRADOR:
    Cliente: ${id}
    CC: No identificado
    Dirección: null
    Teléfono: null

    DETALLES DE LA FACTURA:
    Fecha: ${fecha}, Número de factura: ${generateUniqueId()}
    
    Productos:
    ${product.map((product, index) => `
      ${index + 1}. ${product.name} - ${product.price}
    `).join('\n')}
    
    Total a pagar (iva incluido): ${totalPay + iva}
  `;
  return facturaText;
}


const imprimirFactura = async (id, totalToPay, products) => {
  const device = await navigator.usb.requestDevice({
    filters: [{ vendorId: 0x1234 }] // Identificador de la impresora (debes reemplazarlo con el correcto)
  });

  await device.open();
  await device.selectConfiguration(1);
  await device.claimInterface(0);
  const facturaText = facturaFunction(id, totalToPay, products);
  // Enviar datos a la impresora (dependiendo del modelo de la impresora, puedes enviar comandos en un formato específico)
  const encoder = new TextEncoder();
  const data = encoder.encode(facturaText);
  await device.transferOut(1, data);

  await device.close();
};

